pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address actor, address newOwner) public {
        // Keep the domain wide: any non-admin actor, any new owner.
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));

        // Record the owner before the interaction.
        address ownerBefore = c.owner();

        // Drive c through setOwner as a (generally non-admin) fuzzed actor.
        vm.prank(actor);
        bool ok;
        try c.setOwner(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: either the call succeeded (actor was admin) and owner
        // became newOwner, or the call reverted and owner is untouched —
        // a reverting call must never leave a different owner in place.
        assertTrue(
            ok ? (c.owner() == newOwner) : (c.owner() == ownerBefore),
            "a reverted setOwner must not change owner"
        );
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address caller, address newOwner) public {
        // admin/owner are the deployer (this test contract); exclude the admin so
        // the call path is the failing, non-admin path for ANY fuzzed caller.
        vm.assume(caller != address(this));

        uint256 g0 = gasleft();
        bool ok;
        vm.prank(caller);
        try c.setOwner(newOwner) { ok = true; } catch { ok = false; }
        uint256 used = g0 - gasleft();

        // Reference: for ANY non-admin caller the check fires BEFORE the body,
        // so the failing call never performs the owner storage load/store and
        // costs far less than one cold SSTORE. Mutant: body runs (cold SLOAD of
        // `owner` + cold SSTORE ~22k extra gas) before the require reverts,
        // exceeding the budget. (State is rolled back either way, so gas is the
        // observable difference on c's public surface.)
        assertTrue(!ok && c.owner() == address(this) && used < 35000);
    }
}

