pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address actor, address newOwner) public {
        // Admissible domain: any caller except the admin (deployer = this test contract).
        vm.assume(actor != address(this));

        bool ok;
        vm.prank(actor);
        try c.setOwner(newOwner) { ok = true; } catch { ok = false; }

        // Universal rule: a non-admin call is rejected before any effect.
        // The mutant executes the body, `return true` skips the trailing require,
        // so the call succeeds for a non-admin and this assertion breaks.
        assertTrue(!ok);
    }
}

