// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address admin;

    function setUp() public {
        c = new C();
        admin = address(this); // deploy-time msg.sender == onlyAdmin
    }

    function testFuzz_property(address actor, address newOwner) public {
        // keep the domain wide: any non-admin actor, any target owner
        vm.assume(actor != admin);

        address before = c.owner();

        vm.prank(actor);
        bool ok;
        try c.setOwner(newOwner) returns (bool s) {
            ok = s;
        } catch {
            ok = false;
        }

        // General rule: a non-admin call is rejected outright — it neither
        // succeeds nor leaves any effect. Reference: ok == false AND owner
        // unchanged for every non-admin actor/newOwner. Mutant: the body runs,
        // `return true` skips the post-_; require, so ok == true and owner is
        // changed — breaking the rule.
        assertTrue(!ok && c.owner() == before);
    }
}
